def comps(mat):
    seen=set(); out=[]
    for r in range(len(mat)):
      for c in range(len(mat[0])):
       if mat[r][c]==7 and (r,c) not in seen:
        q=[(r,c)]; seen.add((r,c)); co=[]
        while q:
         x,y=q.pop();co.append((x,y))
         for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
          z=(x+dx,y+dy)
          if 0<=z[0]<len(mat) and 0<=z[1]<len(mat[0]) and mat[z[0]][z[1]]==7 and z not in seen: seen.add(z);q.append(z)
        out.append(co)
    return out
